def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]

    if n <= 3:
        return 'D' if last_o == 'D' else 'C'

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1

    if opp_d == 0:
        return 'C'
    if opp_d == n:
        return 'D'

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    if last_m == 'C' and last_o == 'D':
        if opp_streak >= 2:
            return 'D'
        if opp_d == 1:
            return 'C'

    cnt_c = [0, 0, 0, 0]
    cnt_d = [0, 0, 0, 0]
    mc_obs = 0
    mc_def = 0
    md_obs = 0
    md_def = 0

    for i in range(1, n):
        pm = history[i - 1][0]
        po = history[i - 1][1]
        co = history[i][1]

        idx = (2 if pm == 'D' else 0) + (1 if po == 'D' else 0)
        if co == 'C':
            cnt_c[idx] += 1
        else:
            cnt_d[idx] += 1

        if pm == 'C':
            mc_obs += 1
            if co == 'D':
                mc_def += 1
        else:
            md_obs += 1
            if co == 'D':
                md_def += 1

    if mc_obs >= 4 and md_obs >= 4:
        if mc_def * 20 >= mc_obs * 13 and md_def * 20 <= md_obs * 7:
            return 'D'

    prior_c = (9, 4, 1, 2)
    prior_d = (1, 4, 7, 8)
    probs = []
    for k in range(4):
        total = cnt_c[k] + cnt_d[k] + prior_c[k] + prior_d[k]
        probs.append((cnt_c[k] + prior_c[k]) / float(total))

    r = 100 - n
    values = [0.0, 0.0, 0.0, 0.0]
    choice = [0, 0, 0, 0]

    for _ in range(r):
        prev = values
        new_values = [0.0, 0.0, 0.0, 0.0]
        new_choice = [0, 0, 0, 0]

        for s in range(4):
            p = probs[s]
            q = 1.0 - p

            c_score = 3.0 * p + p * prev[0] + q * prev[1]
            d_score = 1.0 + 4.0 * p + p * prev[2] + q * prev[3]

            if d_score > c_score + 0.2:
                new_values[s] = d_score
                new_choice[s] = 1
            else:
                new_values[s] = c_score
                new_choice[s] = 0

        values = new_values
        choice = new_choice

    state_idx = (2 if last_m == 'D' else 0) + (1 if last_o == 'D' else 0)
    return 'D' if choice[state_idx] else 'C'
